record.field:
for record in records:
    if record.technician_id and record.technician_id.user_id:
        record.activity_schedule(
            "mail.mail_activity_data_todo",
            summary="Nouvelle intervention planifiée",
            note="Vous avez une intervention planifiée : %s" % record.name,
            user_id=record.technician_id.user_id.id,
        )
